    def validate(self, attrs: dict[str, Any]) -> dict[str, Any]:
        """Ensure media is present and within size limits for the chosen source type."""
        source_type = attrs.get(
            "source_type", getattr(self.instance, "source_type", None)
        )
        screenshot = attrs.get("screenshot") or getattr(
            self.instance, "screenshot", None
        )
        audio_file = attrs.get("audio_file") or getattr(
            self.instance, "audio_file", None
        )

        if source_type == "SCREENSHOT" and not screenshot:
            raise serializers.ValidationError(
                "Screenshot is required for screenshot source type"
            )
        if source_type == "VOICE" and not audio_file:
            raise serializers.ValidationError(
                "Audio file is required for voice source type"
            )

        if screenshot and screenshot.size > 10 * 1024 * 1024:  # 10MB
            raise serializers.ValidationError("Screenshot must be less than 10MB")

        if audio_file and audio_file.size > 25 * 1024 * 1024:  # 25MB
            raise serializers.ValidationError("Audio file must be less than 25MB")

        if audio_file:
            allowed_audio_types = VoiceRecordingProcessorService.ALLOWED_AUDIO_TYPES
            content_type = getattr(audio_file, "content_type", None)
            if not content_type:
                guessed = mimetypes.guess_type(audio_file.name)[0]
                content_type = guessed or "application/octet-stream"

            if content_type not in allowed_audio_types:
                raise serializers.ValidationError(
                    f"Unsupported audio type: {content_type}"
                )

        return attrs

