        recipe = obj.linked_recipe
        summary = {
            "id": str(recipe.id),
            "title": recipe.title,
            "difficulty": recipe.difficulty,
            "servings": recipe.servings,
            "prep_time_minutes": recipe.prep_time_minutes,
            "cook_time_minutes": recipe.cook_time_minutes,
            "total_time_minutes": recipe.total_time_minutes,
            "ingredient_count": getattr(obj, "ingredient_count", None)
            or recipe.ingredients.count(),
            "shared_meta_families": FamilyCompactSerializer(
                recipe.shared_meta_families.all(), many=True
            ).data,
        }

        # Add image URL if available
        if recipe.image_key:
            try:
                resolver = _get_presigned_url_resolver_from_context(self.context)
                summary["image_url"] = resolver.resolve(
                    recipe.image_key,
                )
