    def get_reaction_summary(self, obj: Any) -> Any:
        """Get counts of each reaction type with user's reaction status."""
        precomputed_summary = getattr(obj, "_reaction_summary", None)
        if precomputed_summary is not None:
            return precomputed_summary

        from django.db.models import Count

        request = self.context.get("request")
        user = request.user if request else None
        prefetched_reactions = getattr(obj, "_prefetched_reactions", None)

        if prefetched_reactions is not None:
            emoji_counts: dict[str, int] = {}
            user_emojis = set()
            for reaction in prefetched_reactions:
                emoji_counts[reaction.emoji] = emoji_counts.get(reaction.emoji, 0) + 1
                if user and reaction.user_id == user.id:
                    user_emojis.add(reaction.emoji)
        else:
            # Use database aggregation to avoid N+1 queries
            emoji_counts = obj.reactions.values("emoji").annotate(count=Count("id"))

            # Get user's reactions in one query to avoid N+1
            user_emojis = set()
            if user:
                user_emojis = set(
                    obj.reactions.filter(user=user).values_list("emoji", flat=True)
                )

        # Build result with user_reacted status
        result = []
        if prefetched_reactions is not None:
            for emoji, count in emoji_counts.items():
                result.append(
                    {
                        "emoji": emoji,
                        "count": count,
                        "user_reacted": emoji in user_emojis,
                    }
                )
        else:
            for item in emoji_counts:
                result.append(
                    {
                        "emoji": item["emoji"],  # type: ignore[index]
                        "count": item["count"],  # type: ignore[index]
                        "user_reacted": item["emoji"] in user_emojis,  # type: ignore[index]
                    }
                )

        return result

    def get_recent_comments(self, obj: Any) -> Any:
        """Get the 3 most recent comments."""
        prefetched_comments = getattr(obj, "_prefetched_active_comments", None)
        if prefetched_comments is not None:
            comments = prefetched_comments[:3]
        else:
            comments = (
                obj.comments.filter(is_active=True)
                .select_related("author")
                .order_by("-created_at")[:3]
            )
        return FamStreamCommentSerializer(comments, many=True).data

    def get_user_has_viewed(self, obj: Any) -> Any:
        """Check if current user has viewed this post."""
        request = self.context.get("request")
        if not request or not request.user.is_authenticated:
            return False
        annotated_has_viewed = getattr(obj, "has_viewed_for_user", None)
        if annotated_has_viewed is not None:
            return bool(annotated_has_viewed)
        prefetched_views = getattr(obj, "_prefetched_user_views", None)
        if prefetched_views is not None:
            return bool(prefetched_views)
        return obj.views.filter(user=request.user).exists()

