def _request_host_from_context(context: Mapping[str, Any]) -> str | None:
    request = context.get("request")
    if not request:
        return None

    try:
        host_value: str = request.get_host()
        return host_value
    except Exception:
        meta = getattr(request, "META", {}) or {}
        host = meta.get("HTTP_HOST") or meta.get("SERVER_NAME")
        return str(host) if host else None


def _viewer_can_access_arrive_by_fields(
    context: Mapping[str, Any],
