    def validate_email(self, value: str) -> str:
        """Validate email format and check for duplicates"""
        if not value:
            raise serializers.ValidationError("Email is required")

        # Check if this email is already invited to this event
        if self.instance is None:  # Creating new invite
            event = self.initial_data.get("event")
            if (
                event
                and EventInvite.objects.filter(
                    event_id=event, email=value.lower()
                ).exists()
            ):
                raise serializers.ValidationError(
                    "This email has already been invited to this event."
                )

        return value.lower()


class EventDraftSerializer(serializers.ModelSerializer[EventDraft]):
    """Serializer for EventDraft model - AI screenshot and voice processing"""

    creator = UserCompactSerializer(read_only=True)
    screenshot_url = serializers.SerializerMethodField()

    class Meta:
        model = EventDraft
        fields = [
            "id",
            "creator",
            "screenshot",
            "screenshot_url",
            "audio_file",
            "source_type",
            "extracted_data",
            "processing_status",
            "processing_notes",
            "error_message",
            "created_at",
            "updated_at",
            "processed_at",
        ]
        read_only_fields = [
            "id",
            "creator",
            "extracted_data",
            "processing_status",
            "processing_notes",
            "error_message",
            "created_at",
            "updated_at",
            "processed_at",
            "screenshot_url",
        ]

    def validate(self, attrs: dict[str, Any]) -> dict[str, Any]:
        """Ensure media is present and within size limits for the chosen source type."""
        source_type = attrs.get(
            "source_type", getattr(self.instance, "source_type", None)
        )
        screenshot = attrs.get("screenshot") or getattr(
            self.instance, "screenshot", None
        )
        audio_file = attrs.get("audio_file") or getattr(
            self.instance, "audio_file", None
        )

        if source_type == "SCREENSHOT" and not screenshot:
            raise serializers.ValidationError(
                "Screenshot is required for screenshot source type"
            )
        if source_type == "VOICE" and not audio_file:
            raise serializers.ValidationError(
                "Audio file is required for voice source type"
            )

        if screenshot and screenshot.size > 10 * 1024 * 1024:  # 10MB
            raise serializers.ValidationError("Screenshot must be less than 10MB")

        if audio_file and audio_file.size > 25 * 1024 * 1024:  # 25MB
            raise serializers.ValidationError("Audio file must be less than 25MB")

        if audio_file:
            allowed_audio_types = VoiceRecordingProcessorService.ALLOWED_AUDIO_TYPES
            content_type = getattr(audio_file, "content_type", None)
            if not content_type:
                guessed = mimetypes.guess_type(audio_file.name)[0]
                content_type = guessed or "application/octet-stream"

            if content_type not in allowed_audio_types:
                raise serializers.ValidationError(
                    f"Unsupported audio type: {content_type}"
                )

        return attrs

    def get_screenshot_url(self, obj: EventDraft) -> str | None:
        """Get full URL for screenshot"""
        if obj.screenshot:
            request = self.context.get("request")
            if request:
                url = obj.screenshot.url
                return str(request.build_absolute_uri(url))
