        ]

    def get_reaction_summary(self, obj: Any) -> Any:
        """Get counts of each reaction type with user's reaction status."""
        precomputed_summary = getattr(obj, "_reaction_summary", None)
        if precomputed_summary is not None:
            return precomputed_summary

        from django.db.models import Count

        request = self.context.get("request")
        user = request.user if request else None
        prefetched_reactions = getattr(obj, "_prefetched_reactions", None)

        if prefetched_reactions is not None:
            emoji_counts: dict[str, int] = {}
            user_emojis = set()
            for reaction in prefetched_reactions:
                emoji_counts[reaction.emoji] = emoji_counts.get(reaction.emoji, 0) + 1
                if user and reaction.user_id == user.id:
                    user_emojis.add(reaction.emoji)
        else:
            # Use database aggregation to avoid N+1 queries
            emoji_counts = obj.reactions.values("emoji").annotate(count=Count("id"))

            # Get user's reactions in one query to avoid N+1
            user_emojis = set()
            if user:
                user_emojis = set(
                    obj.reactions.filter(user=user).values_list("emoji", flat=True)
                )

        # Build result with user_reacted status
        result = []
        if prefetched_reactions is not None:
            for emoji, count in emoji_counts.items():
                result.append(
                    {
                        "emoji": emoji,
                        "count": count,
                        "user_reacted": emoji in user_emojis,
                    }
                )
        else:
            for item in emoji_counts:
                result.append(
                    {
                        "emoji": item["emoji"],  # type: ignore[index]
                        "count": item["count"],  # type: ignore[index]
                        "user_reacted": item["emoji"] in user_emojis,  # type: ignore[index]
                    }
                )

        return result

    def get_recent_comments(self, obj: Any) -> Any:
        """Get the 3 most recent comments."""
        prefetched_comments = getattr(obj, "_prefetched_active_comments", None)
        if prefetched_comments is not None:
            comments = prefetched_comments[:3]
        else:
            comments = (
                obj.comments.filter(is_active=True)
                .select_related("author")
                .order_by("-created_at")[:3]
            )
        return FamStreamCommentSerializer(comments, many=True).data

    def get_user_has_viewed(self, obj: Any) -> Any:
        """Check if current user has viewed this post."""
        request = self.context.get("request")
        if not request or not request.user.is_authenticated:
            return False
        annotated_has_viewed = getattr(obj, "has_viewed_for_user", None)
        if annotated_has_viewed is not None:
            return bool(annotated_has_viewed)
        prefetched_views = getattr(obj, "_prefetched_user_views", None)
        if prefetched_views is not None:
            return bool(prefetched_views)
        return obj.views.filter(user=request.user).exists()

    def get_linked_event_title(self, obj: Any) -> Any:
        if obj.linked_event:
            return obj.linked_event.title
        return None

    def get_linked_trip_title(self, obj: Any) -> Any:
        if obj.linked_trip:
            return obj.linked_trip.name
        return None

    def get_linked_recipe_summary(self, obj: Any) -> Any:
        """Get summary of linked recipe for feed display."""
        if not obj.linked_recipe:
            return None

        recipe = obj.linked_recipe
        summary = {
            "id": str(recipe.id),
            "title": recipe.title,
            "difficulty": recipe.difficulty,
            "servings": recipe.servings,
            "prep_time_minutes": recipe.prep_time_minutes,
            "cook_time_minutes": recipe.cook_time_minutes,
            "total_time_minutes": recipe.total_time_minutes,
            "ingredient_count": getattr(obj, "ingredient_count", None)
            or recipe.ingredients.count(),
            "shared_meta_families": FamilyCompactSerializer(
                recipe.shared_meta_families.all(), many=True
            ).data,
        }

        # Add image URL if available
        if recipe.image_key:
            try:
                resolver = _get_presigned_url_resolver_from_context(self.context)
                summary["image_url"] = resolver.resolve(
                    recipe.image_key,
                )
            except Exception:
                summary["image_url"] = None
        else:
            summary["image_url"] = None

        return summary


class FamStreamPostCreateSerializer(serializers.ModelSerializer[FamStreamPost]):
    """Serializer for creating posts."""

    family_ids = serializers.ListField(
        child=serializers.UUIDField(),
        required=False,
        help_text="List of family IDs to share with. If empty, shares with all user's families.",
    )

    class Meta:
        model = FamStreamPost
        fields = [
            "content",
            "linked_event",
            "linked_trip",
            "linked_recipe",
            "family_ids",
        ]

    def validate(self, attrs: Any) -> Any:
        """Validate the post data."""
        request = self.context.get("request")
        assert request is not None
        user = request.user

        # Get user's families
        user_family_ids = set(
            FamilyMembership.objects.filter(user=user, is_active=True).values_list(
                "family_id", flat=True
            )
        )

        if not user_family_ids:
            raise serializers.ValidationError(
                "You must belong to at least one family to create a post"
            )

        # Validate family_ids if provided
        family_ids = attrs.get("family_ids", [])
        if family_ids:
            # Convert to set for comparison
            requested_ids = set(family_ids)
            invalid_ids = requested_ids - user_family_ids
            if invalid_ids:
                raise serializers.ValidationError(
                    {"family_ids": "You can only share with families you belong to"}
                )
            attrs["family_ids"] = list(requested_ids)
        else:
            # Default to all user's families
            attrs["family_ids"] = list(user_family_ids)

        attrs = _validate_post_body(attrs)

        # Validate linked event access
        linked_event = attrs.get("linked_event")
        if linked_event:
            if linked_event.family_group_id not in user_family_ids:
                raise serializers.ValidationError(
                    {"linked_event": "You don't have access to this event"}
                )

        # Validate linked trip access
        linked_trip = attrs.get("linked_trip")
        if linked_trip:
            if not user_has_active_trip_access(linked_trip, user):
                raise serializers.ValidationError(
                    {"linked_trip": "You don't have access to this trip"}
                )

        return attrs

    def create(self, validated_data: Any) -> Any:
        """Create post with visibility entries and event media if linked."""
        from django.db import transaction

        from events.models import EventMedia

        family_ids = validated_data.pop("family_ids")
        request = self.context.get("request")
        assert request is not None

        linked_event = validated_data.get("linked_event")

        # Use atomic transaction to prevent orphaned posts
        with transaction.atomic():
            # Create the post
            post = FamStreamPost.objects.create(author=request.user, **validated_data)

            # Create visibility entries
            families = FamilyGroup.objects.filter(id__in=family_ids)
            visibility_entries = [
                FamStreamPostVisibility(post=post, family=family) for family in families
            ]
            FamStreamPostVisibility.objects.bulk_create(visibility_entries)

            # Copy event media if linked_event is provided
            if linked_event:
                event_media = list(
                    EventMedia.secure.for_event(linked_event).order_by(
                        "uploaded_at", "id"
                    )
                )
                media_items = [
                    media
                    for media in event_media
                    if media.media_type in ("PHOTO", "VIDEO")
                ]

                if media_items:
                    famstream_media = []
                    for order, media in enumerate(media_items):
                        famstream_media.append(
                            FamStreamMedia(
                                post=post,
                                media_type="IMAGE"
                                if media.media_type == "PHOTO"
                                else "VIDEO",
                                file_key=media.file_key,
                                thumbnail_key=media.thumbnail_key or "",
                                original_filename=media.original_filename,
                                file_size=media.file_size,
                                content_type=media.content_type,
                                width=media.width,
                                height=media.height,
                                duration=media.duration,
                                order=order,
                            )
                        )
                    FamStreamMedia.objects.bulk_create(famstream_media)

        return post


