            if invalid_ids:
                raise serializers.ValidationError(
                    {"family_ids": "You can only share with families you belong to"}
                )

        attrs = _validate_post_body(attrs, instance=self.instance)

        return attrs

    def update(self, instance: Any, validated_data: Any) -> Any:
        """Update post and visibility."""
        from django.db import transaction

        family_ids = validated_data.pop("family_ids", None)

        # Use atomic transaction to prevent data loss if bulk_create fails
        with transaction.atomic():
            # Update post fields
            for attr, value in validated_data.items():
                setattr(instance, attr, value)
            instance.save()

            # Update visibility if family_ids provided
            if family_ids is not None:
                # Remove old visibility entries
                instance.visibility.all().delete()

                # Create new ones
                families = FamilyGroup.objects.filter(id__in=family_ids)
                visibility_entries = [
                    FamStreamPostVisibility(post=instance, family=family)
                    for family in families
                ]
                FamStreamPostVisibility.objects.bulk_create(visibility_entries)

        return instance


