logger = logging.getLogger(__name__)


def _get_request_host_from_context(context: Mapping[str, object]) -> str | None:
    request = context.get("request")
    if not request:
        return None

    get_host = getattr(request, "get_host", None)
    if not callable(get_host):
        return None

    try:
        return str(get_host())
    except Exception:
        return None


def _get_presigned_url_resolver_from_context(
    context: dict[str, object],
) -> PresignedURLResolver:
    resolver = context.get("presigned_url_resolver")
    if isinstance(resolver, PresignedURLResolver):
        return resolver

    resolver = PresignedURLResolver(
        request_host=_get_request_host_from_context(context),
    )
    context["presigned_url_resolver"] = resolver
    return resolver


def _normalize_post_content(value: object) -> str:
    if value is None:
        return ""
    return str(value).strip()


def _has_linked_content(
    linked_event: Any, linked_trip: Any, linked_recipe: Any
) -> bool:
    return any((linked_event, linked_trip, linked_recipe))


def _validate_post_body(
    attrs: dict[str, object], instance: Any = None
) -> dict[str, object]:
    content = _normalize_post_content(
        attrs.get("content", getattr(instance, "content", ""))
    )
    linked_event = attrs.get("linked_event", getattr(instance, "linked_event", None))
    linked_trip = attrs.get("linked_trip", getattr(instance, "linked_trip", None))
    linked_recipe = attrs.get("linked_recipe", getattr(instance, "linked_recipe", None))

    if not content and not _has_linked_content(
        linked_event, linked_trip, linked_recipe
    ):
        raise serializers.ValidationError(
            {"content": "Post cannot be empty without linked content"}
        )

    attrs["content"] = content
    return attrs


