class FamStreamMediaSerializer(serializers.ModelSerializer[FamStreamMedia]):
    """Serializer for post media with presigned URLs."""

    file_url = serializers.SerializerMethodField()
    thumbnail_url = serializers.SerializerMethodField()

    class Meta:
        model = FamStreamMedia
        fields = [
            "id",
            "media_type",
            "file_url",
            "thumbnail_url",
            "original_filename",
            "file_size",
            "content_type",
            "width",
            "height",
            "duration",
            "order",
            "created_at",
        ]
        read_only_fields = fields

    def _get_request_host(self) -> Any:
        request = self.context.get("request")
        if not request:
            return None

        try:
            return request.get_host()
        except Exception:
            return None

    def get_file_url(self, obj: Any) -> Any:
        """Generate presigned URL for the media file."""
        if not obj.file_key:
            logger.warning(f"FamStreamMedia {obj.id} has no file_key")
            return None

        try:
            resolver = _get_presigned_url_resolver_from_context(self.context)
            url = resolver.resolve(obj.file_key)
            if not url:
                logger.warning(
                    f"Failed to generate presigned URL for FamStreamMedia {obj.id} "
                    f"with key {obj.file_key}"
                )
            return url
        except Exception as e:
            logger.error(
                f"Error generating presigned URL for FamStreamMedia {obj.id} "
                f"with key {obj.file_key}: {e}"
            )
            return None

    def get_thumbnail_url(self, obj: Any) -> Any:
        """Generate presigned URL for thumbnail."""
        if not obj.thumbnail_key:
            return None
        try:
            resolver = _get_presigned_url_resolver_from_context(self.context)
            url = resolver.resolve(obj.thumbnail_key)
            if not url:
                logger.warning(
                    f"Failed to generate thumbnail URL for FamStreamMedia {obj.id} "
                    f"with key {obj.thumbnail_key}"
                )
            return url
        except Exception as e:
            logger.error(
                f"Error generating thumbnail URL for FamStreamMedia {obj.id} "
                f"with key {obj.thumbnail_key}: {e}"
            )
            return None


